elapsed: 10_000
deposited: 1e18
dyadMinted: 0
totalXP: 0

accrualRateModifier: 1e18

adjustedAccrualRate: 1e18 * 1e7 = 1e25

bonus: 1e18

0 + 1e18 != 0
