```solidity
    function withdrawHYPE(
        uint256 elyAssetAmount,
        address receiver
    )
        // ...
    {
        // ...

        // Burn elyAsset tokens
        address elyAssetToken = elytraConfig.getElyAsset();
        IElyERC20(elyAssetToken).burnFrom(msg.sender, elyAssetAmount);

